    43→  console.log(`  ⏱️  Files loaded in ${((Date.now() - loadStart) / 1000).toFixed(1)}s\n`);
    44→
    45→  // ═══════════════════════════════════════════════════════════════════════════
    46→  // PHASE 1: Foundation data (parties + districts run in parallel)
    47→  // ═══════════════════════════════════════════════════════════════════════════
    48→  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
