    74→  await syncDeputyExtendedInfo(infoBase.Deputados, deputyMaps.byDepId, partyMap);
    75→
    76→  console.log(`  ⏱️  Phase 2 completed in ${((Date.now() - phase2Start) / 1000).toFixed(1)}s\n`);
    77→
    78→  // ═══════════════════════════════════════════════════════════════════════════
    79→  // PHASE 3: Data transforms + scraping (all independent, run in parallel)
    80→  // - Initiatives transform (CPU-bound)
    81→  // - Activities transform (CPU-bound)
    82→  // - Attendance scraping (I/O-bound)
    83→  // - Biography scraping (I/O-bound)
    84→  // ═══════════════════════════════════════════════════════════════════════════
    85→  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
