   110→        interventionsByParty,
   111→        partyMap
   112→      );
   113→      console.log('  ✅ Activities complete');
   114→      return interventionsByDeputy;
   115→    })(),
   116→
   117→    // Task 3: Plenary Attendance (I/O-bound scraping with incremental support)
   118→    runStep(
   119→      'Plenary Attendance',
   120→      async () => {
