   137→          `  ✅ Biographies complete (${result.scraped} scraped, ${result.skipped} skipped)`
   138→        );
   139→        return { processed: result.scraped, failed: 0 };
   140→      },
   141→      { critical: false }
   142→    ),
   143→  ]);
   144→
   145→  // Check for any failures in Phase 3
   146→  for (const result of phase3Results) {
   147→    if (result.status === 'rejected') {
   148→      console.error('  ⚠️ Phase 3 task failed:', result.reason);
   149→    }
   150→  }
   151→
   152→  console.log(`\n  ⏱️  Phase 3 completed in ${((Date.now() - phase3Start) / 1000).toFixed(1)}s\n`);
   153→
   154→  // ═══════════════════════════════════════════════════════════════════════════
   155→  // PHASE 4: Statistics (depends on everything above)
   156→  // ═══════════════════════════════════════════════════════════════════════════
   157→  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
